/** Activity types users can log (and later edit or delete); every other type is generated by the system. */
export const manualActivityTypes = ["call", "email", "meeting", "note"] as const;
export type ManualActivityType = (typeof manualActivityTypes)[number];

export function isManualActivityType(activityType: string): activityType is ManualActivityType {
  return manualActivityTypes.some((manualType) => manualType === activityType);
}

export type ModifiableActivityCandidate = { is_system_event: boolean; activity_type: string; created_by: string };

/**
 * Only workspace admins may modify activities created by someone else; this mirrors the database policy.
 * Callers still need to confirm separately that the user can edit the parent record.
 */
export function canModifyManualActivity(
  { isAdmin, userId, activity }: { isAdmin: boolean; userId: string; activity: ModifiableActivityCandidate },
): boolean {
  if (activity.is_system_event || !isManualActivityType(activity.activity_type)) return false;
  return isAdmin || activity.created_by === userId;
}
